N scd.dataset_id = 'CMBP_NET' AND scd.split_level = 0 THEN NULL ELSE scd.pnl_fiscal_year_to_date_reporting_currency END pnl_fiscal_year_to_date_reporting_currency, CASE WHEN scd.dataset_id = 'TOTALFUND' AND scd.split_level = 0 THEN NULL ELSE scd.pnl_fiscal_year_to_date_local_currency END pnl_fiscal_year_to_date_local_currency, perf.pnl_4yp_rc AS pnl_4year_plus_reporting_currency, perf.pnl_4yp_lc AS pnl_4year_plus_local_currency, CASE WHEN scd.dataset_id = 'CMBP_NET' AND scd.split_level = 0 THEN NULL ELSE scd.pnl_5year_roll_reporting_currency END pnl_5year_roll_reporting_currency, CASE WHEN scd.dataset_id = 'TOTALFUND' AND scd.split_level = 0 THEN NULL ELSE scd.pnl_5year_roll_local_currency END pnl_5year_roll_local_currency, scd.last_update FROM performance.scd_performance_bottom_up scd LEFT JOIN (SELECT replace(dataset_id, '_D', '') AS dataset_id, business_date, node_name, "level", time_weighted_return_4yp_rc, CASE WHEN dataset_id = 'TOTALFUND_D' THEN NULL ELSE time_weighted_return_4yp_lc END time_weighted_return_4yp_lc, pnl_4yp_rc, CASE WHEN dataset_id = 'TOTALFUND_D' THEN NULL ELSE pnl_4yp_lc END pnl_4yp_lc FROM performance.perf_bottom_up_monthly WHERE (dataset_id IN ('TOTALFUND_D') AND "level" = 0 AND periods_per_year = 365) OR (dataset_id IN ('ACCOUNTS_BCPP_D', 'ACCOUNTS_ACPP_D') AND "level" = 0 AND periods_per_year = 365) UNION ALL SELECT replace(dataset_id, '_D', '') AS dataset_id, business_date, node_name, "level", time_weighted_return_4yp_rc, time_weighted_return_4yp_lc, pnl_4yp_rc, pnl_4yp_lc FROM performance.perf_top_down_monthly WHERE periods_per_year = 365 AND dataset_id = 'ATP_TF_D') perf ON scd.business_date = CAST(perf.business_date AS varchar) AND scd.dataset_id = perf.dataset_id AND scd.pbor_node_name = perf.node_name AND scd.split_level = perf."level" WHERE scd.periods_per_year = '365' AND ((scd.dataset_id IN ('TOTALFUND', 'CMBP_NET') AND scd.split_level = 0) OR (scd.dataset_id IN ('ACCOUNTS_BCPP', 'ACCOUNTS_ACPP') AND scd.split_level = 0) OR (scd.