_date_reporting_currency, pnl_quarter_to_date_local_currency, pnl_fiscal_year_to_date_reporting_currency, pnl_fiscal_year_to_date_local_currency, pnl_4year_plus_reporting_currency, pnl_4year_plus_local_currency, pnl_5year_roll_reporting_currency, pnl_5year_roll_local_currency]) scd_perf_unpivot(metric, value)), perf AS (SELECT dataset_id, business_date, CASE WHEN dataset_id = 'ATP_BCPP_D' THEN 'Base CPP Benchmark Portfolio' WHEN dataset_id = 'ATP_ACPP_D' THEN 'Additional CPP Benchmark Portfolio' WHEN dataset_id = 'INV_SELECT_TF_D' THEN 'Total Fund Value-Added' WHEN dataset_id = 'INV_SELECT_BCPPD' THEN 'Base CPP Value-Added' WHEN dataset_id = 'INV_SELECT_ACPPD' THEN 'Additional CPP Value-Added' ELSE pbor_node_name END pbor_node_name, split_level, CASE WHEN metric LIKE 'time_weighted_return_%' THEN 'Return' WHEN metric LIKE 'pnl_%' THEN 'Income' END metric_type, CASE WHEN metric LIKE '%_reporting_currency' THEN 'CAD' WHEN metric LIKE '%_local_currency' THEN 'Local' END currency, CASE WHEN metric LIKE '%month_to_date%' THEN 'MTD' WHEN metric LIKE '%quarter_to_date%' THEN 'QTD' WHEN metric LIKE '%fiscal_year_to_date%' THEN 'FYTD' WHEN metric LIKE '%4year_plus%' THEN '4Y+FYTD' WHEN metric LIKE '%5year_roll%' THEN '5Y' ELSE '1D' END period, value FROM (SELECT dataset_id, business_date, node_name AS pbor_node_name, "level" AS split_level, time_weighted_return_rc AS time_weighted_return_reporting_currency, time_weighted_return_lc AS time_weighted_return_local_currency, time_weighted_return_qtd_rc AS time_weighted_return_quarter_to_date_reporting_currency, time_weighted_return_qtd_lc AS time_weighted_return_quarter_to_date_local_currency, time_weighted_return_fytd_rc AS time_weighted_return_fiscal_year_to_date_reporting_currency, time_weighted_return_fytd_lc AS time_weighted_return_fiscal_year_to_date_local_currency, time_weighted_return_4yp_rc AS time_weighted_return_4year_plus_reporting_currency, time_weighted_return_4yp_lc AS time_weighted_return_4year_plus_local_currency